package app.conversions;

import app.UnitOfWork;
import app.application_models.ProductStatus;
import app.dtos.ProductCreate;
import app.dtos.ProductRead;
import app.entities.Category;
import app.errors.NotFoundException;

/** Conversions between the application models and the "products" table: what the service takes and returns. */
public final class ProductConversions {
    private ProductConversions() {}

    /** A Product as the products table takes it. */
    public static ProductCreate productModelToProductCreate(app.application_models.Product model, UnitOfWork uow) {
        Category category = uow.categories().findByName(model.getCategoryName())
                .orElseThrow(() -> new NotFoundException("Category", model.getCategoryName()));
        return new ProductCreate(
                category.getId(),
                model.getName(),
                model.getPrice(),
                model.getStatus() == null ? null : switch (model.getStatus()) { case DRAFT -> "draft"; case LIVE -> "live"; }
        );
    }

    /** A row of the products table as a Product. */
    public static app.application_models.Product productReadToProductModel(ProductRead row, UnitOfWork uow) {
        Category category = uow.categories().findById(row.categoryId()).orElseThrow();
        return app.application_models.Product.builder()
                .id(row.id())
                .name(row.name())
                .price(row.price())
                .status(row.status() == null ? null : switch (row.status()) { case "draft" -> ProductStatus.DRAFT; case "live" -> ProductStatus.LIVE; default -> throw new IllegalArgumentException("No ProductStatus for " + row.status()); })
                .categoryName(category.getName())
                .tagIds(uow.productTags().listByProductId(row.id()).stream().map(item -> item.getTagId()).toList())
                .build();
    }
}

