package app.repositories;

import app.common.Page;
import app.entities.Category;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Stream;

/** Keeps categories rows in memory, for tests and for trying the services without a database. */
public class MemoryCategoryRepository implements CategoryRepository {
    private final Map<List<Object>, Category> rows = new LinkedHashMap<>();
    private long nextId = 1;

    /** The key of a row, as a list of its key values. */
    private static List<Object> keyOf(Category row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getId());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<Category> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryCategoryRepository::keyOf, MemoryCategoryRepository::compareKeys));
    }

    @Override
    public Optional<Category> findById(Integer id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public Page<Category> list(int offset, int limit) {
        List<Category> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
    }

    @Override
    public Optional<Category> findByName(String name) {
        return visible().filter((row) -> Objects.equals(row.getName(), name)).findFirst();
    }

    @Override
    public Category insert(Category entity) {
        if (entity.getId() == null) entity.setId((int) nextId++);
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public Category update(Category entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(Category entity) {
        rows.remove(keyOf(entity));
    }
}

