    protected final Connection connection;

    public SqlCategoryRepository(Connection connection) {
        this.connection = connection;
    }

    @Override
    public Optional<Category> findById(Integer id) {
        return Sql.one(connection, "SELECT " + COLUMNS + " FROM \"categories\" WHERE \"id\" = ?", SqlCategoryRepository::toEntity, id);
    }

    @Override
    public Page<Category> list(int offset, int limit) {
        List<Category> items = Sql.all(connection, "SELECT " + COLUMNS + " FROM \"categories\" ORDER BY \"id\" LIMIT ? OFFSET ?", SqlCategoryRepository::toEntity, limit, offset);
        long total = Sql.one(connection, "SELECT COUNT(*) FROM \"categories\"", (row) -> row.getLong(1)).orElse(0L);
        return new Page<>(items, total, offset, limit);
    }

    @Override
    public Optional<Category> findByName(String name) {
        return Sql.one(connection, "SELECT " + COLUMNS + " FROM \"categories\" WHERE \"name\" = ?", SqlCategoryRepository::toEntity, name);
    }

