    public Category insert(Category entity) {
        try {
            List<String> names = new ArrayList<>();
            List<Object> values = new ArrayList<>();
            if (entity.getId() != null) { names.add("\"id\""); values.add(entity.getId()); }
            if (entity.getName() != null) { names.add("\"name\""); values.add(entity.getName()); }
            String sql = names.isEmpty()
                    ? "INSERT INTO \"categories\" DEFAULT VALUES"
                    : "INSERT INTO \"categories\" (" + String.join(", ", names) + ") VALUES (" + String.join(", ", Collections.nCopies(names.size(), "?")) + ")";
            return Sql.one(connection, sql + " RETURNING " + COLUMNS, (row) -> fill(row, entity), values.toArray())
                    .orElseThrow(() -> new IllegalStateException("The Category just written is not there"));
        } catch (Sql.RefusedException error) {
            throw new ConflictException("Category", "the database refused the change: " + error.getMessage());
        }
    }

    @Override
    public Category update(Category entity) {
        try {
            Sql.run(connection, "UPDATE \"categories\" SET \"name\" = ? WHERE \"id\" = ?", entity.getName(), entity.getId());
        } catch (Sql.RefusedException error) {
            throw new ConflictException("Category", "the database refused the change: " + error.getMessage());
        }
        return Sql.one(connection, "SELECT " + COLUMNS + " FROM \"categories\" WHERE \"id\" = ?", (row) -> fill(row, entity), entity.getId())
                .orElseThrow(() -> new IllegalStateException("The Category just written is not there"));
    }

    @Override
    public void delete(Category entity) {
        try {
            Sql.run(connection, "DELETE FROM \"categories\" WHERE \"id\" = ?", entity.getId());
        } catch (Sql.RefusedException error) {
            throw new ConflictException("Category", "the database refused the change: " + error.getMessage());
        }
    }

    /** The Category of a row read with COLUMNS. */
    private static Category toEntity(ResultSet row) throws SQLException {
        return fill(row, new Category());
    }

