            return Sql.one(connection, sql + " RETURNING " + COLUMNS, (row) -> fill(row, entity), values.toArray())
                    .orElseThrow(() -> new IllegalStateException("The Tag just written is not there"));
        } catch (Sql.RefusedException error) {
            throw new ConflictException("Tag", "the database refused the change: " + error.getMessage());
        }
    }

    @Override
    public Tag update(Tag entity) {
        try {
            Sql.run(connection, "UPDATE \"tags\" SET \"label\" = ? WHERE \"id\" = ?", entity.getLabel(), entity.getId());
        } catch (Sql.RefusedException error) {
            throw new ConflictException("Tag", "the database refused the change: " + error.getMessage());
        }
        return Sql.one(connection, "SELECT " + COLUMNS + " FROM \"tags\" WHERE \"id\" = ?", (row) -> fill(row, entity), entity.getId())
                .orElseThrow(() -> new IllegalStateException("The Tag just written is not there"));
    }

    @Override
    public void delete(Tag entity) {
        try {
            Sql.run(connection, "DELETE FROM \"tags\" WHERE \"id\" = ?", entity.getId());
        } catch (Sql.RefusedException error) {
            throw new ConflictException("Tag", "the database refused the change: " + error.getMessage());
        }
    }

    /** The Tag of a row read with COLUMNS. */
    private static Tag toEntity(ResultSet row) throws SQLException {
        return fill(row, new Tag());
    }

    /** Reads a row selected with COLUMNS into entity. */
    private static Tag fill(ResultSet row, Tag entity) throws SQLException {
        entity.setId(Sql.getInteger(row, 1));
        entity.setLabel(Sql.getString(row, 2));
        return entity;
    }
}

