import org.junit.jupiter.api.Test;

/** Tests of the conversions between the application models and the tables. */
class ConversionsTest {
    private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

    @Test
    void readsCategoryDtoAndWritesItBack() {
        Category row = Factories.addCategory(uow, 1);
        var model = CategoryConversions.categoryReadToCategoryDto(categoryReadOf(row));
        var values = CategoryConversions.categoryDtoToCategoryCreate(model);
        assertEquals(row.getName(), values.name());
    }

    @Test
    void readsProductAndWritesItBack() {
        Product row = Factories.addProduct(uow, 1);
        var model = ProductConversions.productReadToProductModel(productReadOf(row), uow);
        var values = ProductConversions.productModelToProductCreate(model, uow);
        assertEquals(row.getCategoryId(), values.categoryId());
        assertEquals(row.getName(), values.name());
        assertEquals(row.getPrice(), values.price());
        assertEquals(row.getStatus(), values.status());
    }

    @Test
    void readsTagEntityAndWritesItBack() {
        Tag row = Factories.addTag(uow, 1);
