        var values = TagConversions.tagEntityToTagCreate(model);
        assertEquals(row.getLabel(), values.label());
    }

    /** The row as the service returns it. */
    private static CategoryRead categoryReadOf(Category entity) {
        return new CategoryRead(entity.getId(), entity.getName());
